#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — Fresh-Flat redeploy (portfolio-site ticket 13).
#
# The original Supabase project (owned by a former teammate's personal
# account) is unreachable. Target: a fresh, Newton-administered Supabase
# project with the reconstructed schema applied, Fresh-Flat's existing
# Vercel deployment repointed at it, and the live demo confirmed working.
# See NewtonProfile/.scratch/portfolio-site/issues/13-fresh-flat-redeploy.md
# for full background on how the schema was reconstructed.
# ──────────────────────────────────────────────────────────────────────────

REPO_DIR="/c/Users/sageb/Documents/Projects/Fresh_Flat/FreshFlat"
ENV_FILE="$REPO_DIR/.env"
MIGRATION_FILE="$REPO_DIR/supabase/migrations/20260826160000_initial_schema.sql"

TOTAL_STAGES=5

banner "Fresh-Flat redeploy"

# ── Stage 1: Supabase — create the project ─────────────────────────────────
stage "Supabase — create the project"
say "Fresh-Flat needs a Supabase project you administer — the old one belongs"
say "to a former teammate's personal account and is no longer reachable."
open_url "https://supabase.com/dashboard/projects"
step "Sign up / log in, then 'New Project'. Name it e.g. 'fresh-flat', set a"
step "database password (save it — you'll need it if you ever connect via"
step "psql/the CLI directly), pick any region, and create it. Provisioning"
step "takes a minute or two."
step "Once it's ready, go to Project Settings → Data API (or 'API' on older"
step "dashboards). Copy the Project URL."
ask NEXT_PUBLIC_SUPABASE_URL "Paste the Project URL:"
step "On the same page, copy the 'anon' / 'public' key."
ask_secret NEXT_PUBLIC_SUPABASE_ANON_KEY "Paste the anon public key:"
step "Now copy the 'service_role' / 'secret' key — Supabase only shows it"
step "once expanded; treat it like a password, it bypasses row security."
ask_secret SUPABASE_SERVICE_ROLE_KEY "Paste the service_role key:"
write_env NEXT_PUBLIC_SUPABASE_URL "$NEXT_PUBLIC_SUPABASE_URL"
write_env NEXT_PUBLIC_SUPABASE_ANON_KEY "$NEXT_PUBLIC_SUPABASE_ANON_KEY"
write_env SUPABASE_SERVICE_ROLE_KEY "$SUPABASE_SERVICE_ROLE_KEY"
note "All three written to $ENV_FILE — this file is already gitignored."

# ── Stage 2: apply the schema ───────────────────────────────────────────────
stage "Apply the schema to the new project"
say "No schema was ever committed for the original project, so this is a"
say "from-scratch rebuild reconstructed from the application code — 6 tables"
say "plus the foreign keys PostgREST needs for the app's embedded selects to"
say "work. Full file: $MIGRATION_FILE"
say "This writes real tables to a brand-new empty database — safe, but worth"
say "reading the migration file once before pasting it in."
open_url "https://supabase.com/dashboard/project/_/sql/new"
step "In the SQL Editor, open $MIGRATION_FILE in your own editor, copy its"
step "entire contents, paste into the SQL Editor, and click 'Run'."
step "You should see 'Success. No rows returned.' — if it errors instead,"
step "stop and report the exact error rather than retrying blindly; a"
step "partial apply can leave some tables created and others not."
confirm "Did the migration run successfully with no errors?" || {
  SKIPPED+=("apply $MIGRATION_FILE via the Supabase SQL Editor")
  warn "skipped — nothing downstream will work until this is applied."
}

# ── Stage 3: OpenAI — API key ───────────────────────────────────────────────
stage "OpenAI — API key for recipe generation"
say "model/recipe.js calls OpenAI's API directly (gpt-4o-mini) to generate"
say "recipes from pantry ingredients. This is unrelated to the database"
say "change, but the original key may be as unreachable as the old Supabase"
say "project if it also belonged to a teammate — worth confirming either way."
open_url "https://platform.openai.com/api-keys"
step "If you already have a working key you administer, reuse it. Otherwise"
step "click 'Create new secret key', name it (e.g. 'fresh-flat'), and copy"
step "it — OpenAI only shows it once."
ask_secret OPENAI_API_KEY "Paste the OpenAI API key (OPENAI_API_KEY):"
write_env OPENAI_API_KEY "$OPENAI_API_KEY"

# ── Stage 4: repoint the existing Vercel deployment ─────────────────────────
stage "Vercel — update environment variables and redeploy"
say "fresh-flat.vercel.app is already a live Vercel project — this isn't a"
say "fresh import, just repointing its env vars at the new Supabase project"
say "and OpenAI key, then redeploying."
open_url "https://vercel.com/dashboard"
step "Open the Fresh-Flat project → Settings → Environment Variables."
step "For each of the four variables below, edit (or add) it, scoped to"
step "Production, with the value you just captured:"
note "  NEXT_PUBLIC_SUPABASE_URL      = ${NEXT_PUBLIC_SUPABASE_URL:0:30}...(hidden)"
note "  NEXT_PUBLIC_SUPABASE_ANON_KEY = ...(hidden)"
note "  SUPABASE_SERVICE_ROLE_KEY     = ...(hidden)"
note "  OPENAI_API_KEY                = ...(hidden)"
step "Go to the Deployments tab → latest deployment → ⋯ → Redeploy."
step "Env var edits don't apply to an already-built deployment — the"
step "redeploy is required, not optional."
pause "Press Enter once the redeploy has finished."

# ── Stage 5: verify the live deployment ─────────────────────────────────────
stage "Verify the live deployment"
open_url "https://fresh-flat.vercel.app/"
step "Sign up for a new account (this is a fresh database — nothing from"
step "the old project carries over, including any existing accounts)."
step "Create a flat, add a pantry ingredient, generate an AI recipe from"
step "it, and save the recipe."
if ! confirm "Did signup, the flat, the pantry ingredient, and the AI recipe all work?"; then
  warn "If signup/login failed: double-check the three Supabase env vars in"
  warn "Vercel match the new project exactly, and that the redeploy actually"
  warn "picked them up (Deployments tab should show a build after you saved"
  warn "the env vars, not before)."
  warn "If recipe generation failed: check OPENAI_API_KEY the same way, and"
  warn "confirm the key has available quota on platform.openai.com/usage."
  SKIPPED+=("confirm full signup → flat → ingredient → recipe flow on fresh-flat.vercel.app")
fi
# ──────────────────────────────────────────────────────────────────────────

finish
